def _list_files(self):
    """临时目录内全部文件的相对路径列表（排序）。"""
    found = []
    for root, _dirs, files in os.walk(self.tmpdir):
        for name in files:
            found.append(os.path.relpath(os.path.join(root, name), self.tmpdir))
    return sorted(found)

